CREATE TABLE branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, city text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('sales','inventory','manager','admin')), active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions (token_hash text PRIMARY KEY, employee_id uuid NOT NULL REFERENCES employees(id), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_employee ON sessions(employee_id);
CREATE TABLE vehicle_models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand text NOT NULL, name text NOT NULL, variant text NOT NULL, fuel text NOT NULL, transmission text NOT NULL, base_price_paise bigint NOT NULL CHECK(base_price_paise > 0), image_key text NOT NULL DEFAULT 'suv', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(brand,name,variant));
CREATE TABLE vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vin text NOT NULL UNIQUE, model_id uuid NOT NULL REFERENCES vehicle_models(id), branch_id uuid NOT NULL REFERENCES branches(id), color text NOT NULL, status text NOT NULL CHECK(status IN ('in_transit','available','reserved','sold')), created_at timestamptz NOT NULL DEFAULT now(), received_at timestamptz);
CREATE INDEX vehicles_scope ON vehicles(branch_id,model_id,status);
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL CHECK(phone ~ '^[0-9]{10,15}$'), email text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), vehicle_id uuid NOT NULL REFERENCES vehicles(id), employee_id uuid NOT NULL REFERENCES employees(id), status text NOT NULL CHECK(status IN ('confirmed','cancelled','converted')), notes text NOT NULL DEFAULT '', booked_at timestamptz NOT NULL DEFAULT now(), cancelled_at timestamptz, converted_at timestamptz);
CREATE UNIQUE INDEX one_active_booking_per_vin ON bookings(vehicle_id) WHERE status='confirmed';
CREATE INDEX bookings_customer ON bookings(customer_id);
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES bookings(id), base_price_paise bigint NOT NULL CHECK(base_price_paise>0), extras_paise bigint NOT NULL CHECK(extras_paise>=0), tax_paise bigint NOT NULL CHECK(tax_paise>=0), total_paise bigint NOT NULL CHECK(total_paise=base_price_paise+extras_paise+tax_paise), snapshot jsonb NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','delivered')), created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, delivered_by uuid REFERENCES employees(id));
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), invoice_ref text NOT NULL UNIQUE, amount_paise bigint NOT NULL CHECK(amount_paise>0), issued_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), amount_paise bigint NOT NULL CHECK(amount_paise>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid')), created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz, creator_id uuid NOT NULL REFERENCES employees(id), reviewer_id uuid REFERENCES employees(id), CHECK((status='paid')=(paid_at IS NOT NULL)));
CREATE INDEX payments_order ON payment_requests(order_id);
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), category text NOT NULL CHECK(category IN ('identity','address','insurance','registration')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')), storage_key text NOT NULL UNIQUE, filename text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size>0 AND size<=4194304), uploader_id uuid NOT NULL REFERENCES employees(id), reviewer_id uuid REFERENCES employees(id), replaces_id uuid REFERENCES documents(id), reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
CREATE INDEX documents_order ON documents(order_id,category,status);
CREATE VIEW order_facts AS
 SELECT o.*, b.customer_id,b.vehicle_id,b.employee_id,b.booked_at,b.notes,v.vin,v.branch_id,v.model_id,v.color,v.status AS vehicle_status,
 m.brand,m.name AS model_name,m.variant,m.image_key,c.name AS customer_name,br.name AS branch_name,i.invoice_ref,i.issued_at,
 coalesce(p.paid_paise,0)::text AS paid_paise,coalesce(p.pending_paise,0)::text AS pending_paise,
 (o.total_paise-coalesce(p.paid_paise,0))::text AS outstanding_paise,
 coalesce(d.identity_verified,false) AS identity_verified,coalesce(d.address_verified,false) AS address_verified,
 (o.status='open' AND v.status='reserved' AND o.total_paise=coalesce(p.paid_paise,0) AND coalesce(d.identity_verified,false) AND coalesce(d.address_verified,false)) AS ready
 FROM orders o JOIN bookings b ON b.id=o.booking_id JOIN vehicles v ON v.id=b.vehicle_id
 JOIN vehicle_models m ON m.id=v.model_id JOIN customers c ON c.id=b.customer_id JOIN branches br ON br.id=v.branch_id JOIN invoices i ON i.order_id=o.id
 LEFT JOIN (SELECT order_id,sum(amount_paise) FILTER(WHERE status='paid') AS paid_paise,sum(amount_paise) FILTER(WHERE status='pending') AS pending_paise FROM payment_requests GROUP BY order_id) p ON p.order_id=o.id
 LEFT JOIN (SELECT d.order_id,bool_or(d.category='identity' AND d.status='verified') AS identity_verified,bool_or(d.category='address' AND d.status='verified') AS address_verified FROM documents d WHERE NOT EXISTS(SELECT 1 FROM documents newer WHERE newer.replaces_id=d.id) GROUP BY d.order_id) d ON d.order_id=o.id;
CREATE FUNCTION protect_order_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.base_price_paise<>OLD.base_price_paise OR NEW.extras_paise<>OLD.extras_paise OR NEW.tax_paise<>OLD.tax_paise OR NEW.total_paise<>OLD.total_paise OR NEW.snapshot<>OLD.snapshot OR NEW.booking_id<>OLD.booking_id THEN RAISE EXCEPTION 'Immutable order snapshot' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_order BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION protect_order_snapshot();
CREATE FUNCTION protect_invoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable invoice' USING ERRCODE='23514'; END $$;
CREATE TRIGGER immutable_invoice BEFORE UPDATE OR DELETE ON invoices FOR EACH ROW EXECUTE FUNCTION protect_invoice();
